o=ROOT/"phase53";protocol=json.loads((o/"protocol.json").read_text());assert json.loads((o/"graph_audit.json").read_text())["status"]=="PASS";assert json.loads((ROOT/"phase52/audit.json").read_text())["status"]=="PASS";rows=[];audits=[];parent=torch.load(ROOT/"phase28/mixed_joint_0/model.pt",map_location="cpu",weights_only=False)["state"];layout=json.loads((ROOT/"phase48/parameter_layout.json").read_text());writable={p["name"] for p in layout["parameters"]}
