 for target in ["current","future"]:
  z=np.load(o/("static_"+target)/f"s{sid:02d}.npz");assert np.array_equal(y,z["y"]);pr=z["predictions"];name="static_"+target;preds[name]=pr;preds[name+"_ema08"]=ema(pr,.8);preds[name+"_ema05"]=ema(pr,.5)
 for variant in protocol["variants"]:
  for trajectory in protocol["trajectories"]:
   name=variant+"_"+trajectory;folder=o/name;assert (folder/"complete.json").exists();z=np.load(folder/f"s{sid:02d}.npz");meta=json.loads((folder/f"s{sid:02d}.json").read_text());p=z["p"];assert np.array_equal(y,z["y"]) and np.isfinite(p).all() and abs(p.sum(1)-1).max()<1e-5;assert np.isfinite(z["loss"]).all() and np.isfinite(z["gradient_norm"]).all();assert meta["nonwritable_unchanged"] and meta["radius_verified"];assert abs(metrics(y,p)["macro_f1"]-meta["metrics"]["macro_f1"])<1e-12
